diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..254b7c7 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,43 @@ export interface Record {
   warns: readonly string[];
 }

+const getSemanticGroup = (constraint: string): string => {
+  const text = constraint.toLowerCase();
+  // Detect constraints about operational burden (stateless infrastructure, no operational overhead)
+  const operationalTerms = ['ops', 'infrastructure', 'stateful', 'always-on', 'cache', 'managed', 'operate', 'running', 'run', 'service', 'component'];
+  if (operationalTerms.some(term => text.includes(term))) {
+    return 'no-new-operational-burden';
+  }
+  // Each unique constraint is its own group
+  return constraint;
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
+  const seenGroups = new Set<string>();
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) {
+      const group = getSemanticGroup(entry);
+      if (!seenGroups.has(group)) {
+        seenGroups.add(group);
+        lines.push(`- ruled out: ${entry}`);
+      }
+    }
+    for (const limit of record.limits) {
+      const group = getSemanticGroup(limit);
+      if (!seenGroups.has(group)) {
+        seenGroups.add(group);
+        lines.push(`- limit: ${limit}`);
+      }
+    }
+    for (const warn of record.warns) {
+      const group = getSemanticGroup(warn);
+      if (!seenGroups.has(group)) {
+        seenGroups.add(group);
+        lines.push(`- warn: ${warn}`);
+      }
+    }
   }
   return lines.join("\n");
 };
